SELECT t.portfolio_transaction_id, t.portfolio_id, t.holding_id, t.product_id, t.transaction_type, t.amount, t.quantity, t.unit_price, t.status, t.scheduled_at, t.processed_at, t.event_key, t.idempotency_key, t.detail_json, t.created_at, p.display_name AS product_display_name FROM portfolio_transactions t LEFT JOIN financial_products p ON p.product_id = t.product_id WHERE t.portfolio_id = #{portfolioId}
AND t.transaction_type = #{transactionType}
AND t.portfolio_transaction_id < #{cursorId}
ORDER BY t.portfolio_transaction_id DESC LIMIT #{limit}

SELECT 
FROM portfolio_transactions
WHERE status = 'SCHEDULED'
  AND scheduled_at <= #{processUntil}
ORDER BY scheduled_at, portfolio_transaction_id
LIMIT #{limit}

mapper.update:
UPDATE portfolio_transactions
SET status = 'COMPLETED',
    processed_at = #{processedAt},
    detail_json = #{detailJson}
WHERE portfolio_transaction_id = #{portfolioTransactionId}
  AND status IN ('SCHEDULED', 'FAILED')

UPDATE portfolio_transactions
SET status = 'FAILED',
    detail_json = #{detailJson}
WHERE portfolio_transaction_id = #{portfolioTransactionId}
  AND status IN ('SCHEDULED', 'FAILED')
